        await h.ruth.locator('.nav-item[data-view="members"]').click();
        act = () => h.ruth.locator('[data-member-id="user-owen"]').click();
      } else act = () => h.ruth.locator('[data-ballot-action="'+family+'"][data-id="'+h.familyId+'"]').click();
